    33	        vertical: CONST.MODAL.ANCHOR_ORIGIN_VERTICAL.TOP, // we assume that popover menu opens below the button, anchor is at TOP
    34	    },
    35	    paymentMethodDropdownAnchorAlignment = {
    36	        horizontal: CONST.MODAL.ANCHOR_ORIGIN_HORIZONTAL.RIGHT, // caret for dropdown is at right, so horizontal anchor is at RIGHT
    37	        vertical: CONST.MODAL.ANCHOR_ORIGIN_VERTICAL.TOP, // we assume that popover menu opens below the button, anchor is at TOP
    38	    },
    39	    buttonSize = CONST.DROPDOWN_BUTTON_SIZE.MEDIUM,
    40	    chatReportID = '',
    41	    currency = CONST.CURRENCY.USD,
    42	    enablePaymentsRoute,
    43	    iouReport,
    44	    isDisabled = false,
    45	    isLoading = false,
    46	    formattedAmount = '',
    47	    onPress,
    48	    pressOnEnter = false,
    49	    policyID = '-1',
    50	    shouldHidePaymentOptions = false,
    51	    shouldShowApproveButton = false,
    52	    shouldDisableApproveButton = false,
    53	    style,
    54	    disabledStyle,
    55	    shouldShowPersonalBankAccountOption = false,
    56	    enterKeyEventListenerPriority = 0,
    57	    confirmApproval,
    58	    useKeyboardShortcuts = false,
    59	    onPaymentOptionsShow,
    60	    onPaymentOptionsHide,
    61	}: SettlementButtonProps) {
    62	    const {translate} = useLocalize();
    63	    const {isOffline} = useNetwork();
    64	    // The app would crash due to subscribing to the entire report collection if chatReportID is an empty string. So we should have a fallback ID here.
    65	    const [chatReport] = useOnyx(`${ONYXKEYS.COLLECTION.REPORT}${chatReportID || -1}`);
    66	    const [lastPaymentMethod = '-1', lastPaymentMethodResult] = useOnyx(ONYXKEYS.NVP_LAST_PAYMENT_METHOD, {selector: (paymentMethod) => paymentMethod?.[policyID]});
    67	    const isLoadingLastPaymentMethod = isLoadingOnyxValue(lastPaymentMethodResult);
    68	    const [policy] = useOnyx(`${ONYXKEYS.COLLECTION.POLICY}${policyID}`);
    69	    const isInvoiceReport = (!isEmptyObject(iouReport) && ReportUtils.isInvoiceReport(iouReport)) || false;
    70	    const shouldShowPaywithExpensifyOption = !shouldHidePaymentOptions && policy?.reimbursementChoice !== CONST.POLICY.REIMBURSEMENT_CHOICES.REIMBURSEMENT_MANUAL;
    71	    const shouldShowPayElsewhereOption = !shouldHidePaymentOptions && !isInvoiceReport;
