    81	            [CONST.IOU.PAYMENT_TYPE.VBBA]: {
    82	                text: translate('iou.settleExpensify', {formattedAmount}),
    83	                icon: Expensicons.Wallet,
    84	                value: CONST.IOU.PAYMENT_TYPE.VBBA,
