    89	                value: CONST.IOU.PAYMENT_TYPE.ELSEWHERE,
    90	            },
    91	        };
    92	        const approveButtonOption = {
    93	            text: translate('iou.approve'),
    94	            icon: Expensicons.ThumbsUp,
    95	            value: CONST.IOU.REPORT_ACTION_TYPE.APPROVE,
    96	            disabled: !!shouldDisableApproveButton,
    97	        };
    98	        const canUseWallet = !isExpenseReport && !isInvoiceReport && currency === CONST.CURRENCY.USD;
    99	
   100	        // Only show the Approve button if the user cannot pay the expense
   101	        if (shouldHidePaymentOptions && shouldShowApproveButton) {
   102	            return [approveButtonOption];
   103	        }
   104	
   105	        // To achieve the one tap pay experience we need to choose the correct payment type as default.
   106	        if (canUseWallet) {
   107	            buttonOptions.push(paymentMethods[CONST.IOU.PAYMENT_TYPE.EXPENSIFY]);
   108	        }
   109	        if (isExpenseReport && shouldShowPaywithExpensifyOption) {
   110	            buttonOptions.push(paymentMethods[CONST.IOU.PAYMENT_TYPE.VBBA]);
   111	        }
   112	        if (shouldShowPayElsewhereOption) {
   113	            buttonOptions.push(paymentMethods[CONST.IOU.PAYMENT_TYPE.ELSEWHERE]);
   114	        }
   115	
   116	        if (isInvoiceReport) {
   117	            if (ReportUtils.isIndividualInvoiceRoom(chatReport)) {
   118	                buttonOptions.push({
