   138	                backButtonText: translate('iou.business'),
   139	                subMenuItems: [
   140	                    {
   141	                        text: translate('iou.payElsewhere', {formattedAmount: ''}),
   142	                        icon: Expensicons.Cash,
   143	                        value: CONST.IOU.PAYMENT_TYPE.ELSEWHERE,
   144	                        onSelected: () => onPress(CONST.IOU.PAYMENT_TYPE.ELSEWHERE, true),
