   164	        iouReport,
   165	        translate,
   166	        formattedAmount,
   167	        shouldDisableApproveButton,
   168	        isInvoiceReport,
   169	        currency,
   170	        shouldHidePaymentOptions,
   171	        shouldShowApproveButton,
   172	        shouldShowPaywithExpensifyOption,
   173	        shouldShowPayElsewhereOption,
   174	        chatReport,
   175	        onPress,
   176	    ]);
   177	
   178	    const selectPaymentType = (event: KYCFlowEvent, iouPaymentType: PaymentMethodType, triggerKYCFlow: TriggerKYCFlow) => {
   179	        if (policy && SubscriptionUtils.shouldRestrictUserBillableActions(policy.id)) {
   180	            Navigation.navigate(ROUTES.RESTRICTED_ACTION.getRoute(policy.id));
