   187	            return;
   188	        }
   189	
   190	        if (iouPaymentType === CONST.IOU.REPORT_ACTION_TYPE.APPROVE) {
   191	            if (confirmApproval) {
   192	                confirmApproval();
   193	            } else {
   194	                IOU.approveMoneyRequest(iouReport);
   195	            }
   196	            return;
   197	        }
   198	
   199	        playSound(SOUNDS.SUCCESS);
   200	        onPress(iouPaymentType);
   201	    };
   202	
   203	    const savePreferredPaymentMethod = (id: string, value: PaymentMethodType) => {
   204	        IOU.savePreferredPaymentMethod(id, value);
   205	    };
   206	
   207	    return (
   208	        <KYCWall
   209	            onSuccessfulKYC={(paymentType) => onPress(paymentType)}
   210	            enablePaymentsRoute={enablePaymentsRoute}
   211	            addBankAccountRoute={addBankAccountRoute}
   212	            addDebitCardRoute={addDebitCardRoute}
   213	            isDisabled={isOffline}
   214	            source={CONST.KYC_WALL_SOURCE.REPORT}
   215	            chatReportID={chatReportID}
   216	            iouReport={iouReport}
   217	            anchorAlignment={kycWallAnchorAlignment}
   218	            shouldShowPersonalBankAccountOption={shouldShowPersonalBankAccountOption}
   219	        >
