   221	                <ButtonWithDropdownMenu<PaymentType>
   222	                    success
   223	                    onOptionsMenuShow={onPaymentOptionsShow}
   224	                    onOptionsMenuHide={onPaymentOptionsHide}
   225	                    buttonRef={buttonRef}
   226	                    shouldAlwaysShowDropdownMenu={isInvoiceReport}
   227	                    customText={isInvoiceReport ? translate('iou.settlePayment', {formattedAmount}) : undefined}
   228	                    menuHeaderText={isInvoiceReport ? translate('workspace.invoices.paymentMethods.chooseInvoiceMethod') : undefined}
   229	                    isSplitButton={!isInvoiceReport}
   230	                    isDisabled={isDisabled}
   231	                    isLoading={isLoading}
   232	                    onPress={(event, iouPaymentType) => selectPaymentType(event, iouPaymentType, triggerKYCFlow)}
   233	                    pressOnEnter={pressOnEnter}
   234	                    options={paymentButtonOptions}
   235	                    onOptionSelected={(option) => {
   236	                        if (policyID === '-1') {
   237	                            return;
   238	                        }
   239	                        savePreferredPaymentMethod(policyID, option.value);
   240	                    }}
   241	                    style={style}
   242	                    disabledStyle={disabledStyle}
   243	                    buttonSize={buttonSize}
   244	                    anchorAlignment={paymentMethodDropdownAnchorAlignment}
   245	                    enterKeyEventListenerPriority={enterKeyEventListenerPriority}
   246	                    useKeyboardShortcuts={useKeyboardShortcuts}
   247	                />
   248	            )}
   249	        </KYCWall>
   250	    );
   251	}
   252	
   253	SettlementButton.displayName = 'SettlementButton';
   254	
   255	export default SettlementButton;
   256

